import { useEffect, useState } from 'react';
import { useParams } from 'react-router-dom';
import { getProduct } from '../services/api';
import { useCart } from '../context/CartContext';
import { useAuth } from '../context/AuthContext';
import { toast } from 'react-toastify';
import './ProductDetailPage.css';

const PALETTE = ['#c8bfb0','#2c2825','#b8c4c0','#d4c4b8','#e8e0d0','#3a2e28','#b8a890','#c8d0c8'];

export default function ProductDetailPage() {
  const { id } = useParams();
  const [product, setProduct] = useState(null);
  const [selectedSize, setSelectedSize] = useState('');
  const [selectedColor, setSelectedColor] = useState('');
  const [qty, setQty] = useState(1);
  const { add, loading } = useCart();
  const { user } = useAuth();

  useEffect(() => {
    getProduct(id).then(({ data }) => {
      setProduct(data);
      setSelectedSize(data.sizes?.[0] || '');
      setSelectedColor(data.colors?.[0] || '');
    });
  }, [id]);

  const handleAdd = async () => {
    if (!user) { toast.info('Please login first'); return; }
    await add(product._id, qty, selectedSize, selectedColor);
    toast.success('Added to cart!');
  };

  if (!product) return <div className="page-loader"><div className="spinner" /></div>;

  const colorIdx = id ? id.charCodeAt(id.length - 1) % PALETTE.length : 0;
  const bg = PALETTE[colorIdx];

  return (
    <div className="detail-page">
      <div className="detail-img" style={{ background: `linear-gradient(160deg,${bg}dd,${bg}88)` }}>
        {product.isNew && <span className="badge badge-new" style={{position:'absolute',top:'1.5rem',left:'1.5rem'}}>New</span>}
        {product.originalPrice && <span className="badge badge-sale" style={{position:'absolute',top:'1.5rem',left:product.isNew?'5rem':'1.5rem'}}>Sale</span>}
      </div>

      <div className="detail-info">
        <div className="detail-brand">{product.brand}</div>
        <h1 className="detail-name">{product.name}</h1>
        <div className="detail-price">
          {product.originalPrice && (
            <span className="detail-original">₹{product.originalPrice.toLocaleString()}</span>
          )}
          <span>₹{product.price.toLocaleString()}</span>
        </div>
        <p className="detail-desc">{product.description}</p>

        {product.sizes?.length > 0 && (
          <div className="detail-section">
            <div className="detail-section-label">Size</div>
            <div className="size-group">
              {product.sizes.map((s) => (
                <button
                  key={s}
                  className={`size-btn ${selectedSize === s ? 'active' : ''}`}
                  onClick={() => setSelectedSize(s)}
                >{s}</button>
              ))}
            </div>
          </div>
        )}

        {product.colors?.length > 0 && (
          <div className="detail-section">
            <div className="detail-section-label">Color — {selectedColor}</div>
            <div className="color-group">
              {product.colors.map((c) => (
                <button
                  key={c}
                  className={`color-btn ${selectedColor === c ? 'active' : ''}`}
                  onClick={() => setSelectedColor(c)}
                >{c}</button>
              ))}
            </div>
          </div>
        )}

        <div className="detail-section">
          <div className="detail-section-label">Quantity</div>
          <div className="qty-group">
            <button className="qty-btn" onClick={() => setQty(Math.max(1, qty - 1))}>−</button>
            <span className="qty-val">{qty}</span>
            <button className="qty-btn" onClick={() => setQty(qty + 1)}>+</button>
          </div>
        </div>

        <button className="btn btn-accent btn-add" onClick={handleAdd} disabled={loading}>
          {loading ? 'Adding...' : 'Add to Cart'}
        </button>

        <div className="detail-meta">
          <div>Stock: <strong>{product.stock} left</strong></div>
          <div>Category: <strong>{product.category}</strong></div>
          <div>Rating: <strong>{'★'.repeat(Math.round(product.rating))}{'☆'.repeat(5 - Math.round(product.rating))} ({product.numReviews})</strong></div>
        </div>
      </div>
    </div>
  );
}
